/**
 * The op-graph: a serializable tree of modeling operations.
 *
 * The authoring API (api.ts) builds one of these; a Kernel (kernel.ts)
 * evaluates it into geometry. Nothing here computes geometry, which is what
 * lets us swap the mesh/CSG kernel for a Rust B-rep kernel later without
 * touching the editor, viewport, or authoring surface.
 *
 * `OpNode` is the single-source contract defined in `schema/opgraph.odk.yaml`
 * and generated by ODK into `opgraph.gen.ts`; this module re-exports it so the
 * same contract backs the TypeScript app and the Rust/WASM kernel. Regenerate
 * with `bun opgraph:generate`. `Vec3` is a local alias for the fixed-length
 * triple ODK emits inline, kept for the authoring API and callers.
 */

import type { OpNode } from "./opgraph.gen";

export type { OpNode } from "./opgraph.gen";

export type Vec3 = [number, number, number];

/** Why a graph needs the B-rep kernel, in terms a user would recognize */
export type BrepNeed = "fillet" | "text" | "svg" | "sketch";

/**
 * The first reason the graph needs the B-rep (OCCT) kernel, or null when the
 * mesh and Rust kernels can evaluate it: an exact-geometry op (fillet,
 * chamfer, shell), text or SVG outlines, or combined 2D sketches (offsets and
 * 2D booleans, which need planar clipping). Walks the whole tree, recursing
 * through single-child transforms and the children arrays of boolean ops.
 */
export function brepNeed(node: OpNode): BrepNeed | null {
  switch (node.op) {
    case "fillet":
    case "chamfer":
    case "shell":
      return "fillet";
    case "text2d":
      return "text";
    case "svg2d":
      return "svg";
    case "offset2d":
    case "union2d":
    case "difference2d":
    case "intersect2d":
      return "sketch";
    // Simple single-ring profiles tessellate in the mesh kernel (as the child of
    // a sweep); a bare one errors there the same as it would in B-rep
    case "circle2d":
    case "rect2d":
    case "polygon2d":
      return null;
    // A sweep follows its profile: a simple ring stays in the mesh kernel, a
    // curved/combined profile forces B-rep
    case "extrude":
    case "revolve":
    case "translate":
    case "rotate":
    case "scale":
    case "mirror":
    // A 2D transform follows its profile too: a transformed simple ring still
    // tessellates in the mesh kernel, a transformed curved/combined one stays
    // B-rep
    case "translate2d":
    case "rotate2d":
    case "scale2d":
    case "mirror2d":
      return brepNeed(node.child);
    case "union":
    case "difference":
    case "intersect":
    case "hull":
      for (const child of node.children) {
        const need = brepNeed(child);
        if (need) return need;
      }
      return null;
    case "cube":
    case "sphere":
    case "cylinder":
    case "cone":
    case "polyhedron":
      return null;
  }
}

/**
 * Whether the graph contains anything only the B-rep (OCCT) kernel can
 * evaluate (see {@link brepNeed}). The mesh and Rust kernels reject these, so
 * the Studio uses this to load and switch to the B-rep kernel on demand.
 */
export function requiresBrep(node: OpNode): boolean {
  return brepNeed(node) !== null;
}

/**
 * Whether the Studio should load and switch to the B-rep kernel before
 * evaluating. True only when the graph needs B-rep ops and the active kernel is
 * not already B-rep, so an explicit non-B-rep choice stays put for models that
 * need no exact geometry, and the switch cannot re-trigger itself once "brep"
 * is the active kernel.
 */
export function shouldAutoSwitchToBrep(
  node: OpNode,
  activeKernelKey: string,
): boolean {
  return activeKernelKey !== "brep" && requiresBrep(node);
}
